/bin/zsh -lc "git diff -- ledger.py .agent/CONTINUITY.md && git status --short && python3 -m py_compile ledger.py tests/test_existing.py tests/test_requirements.py && python3 - <<'PY'
from ledger import Ledger

ledger = Ledger()
assert ledger.apply_batch([]) == []
assert ledger.balances == {}
assert ledger.audit == []
assert ledger.apply_batch((entry for entry in ((\"a\", 1), (\"a\", -1)))) == [1, 0]
for invalid in (None, 42):
    try:
        Ledger().apply_batch(invalid)
    except ValueError:
        pass
    else:
        raise AssertionError(f\"expected ValueError for {invalid"'!r}")
PY
date -u +%Y-%m-%dT%H:%M:%SZ'

